const CATEGORIES=['Produce','Dairy','Meat and seafood','Bakery','Frozen food','Pantry','Drinks','Household','Other'];
const EMOJI={'Produce':'🥬','Dairy':'🥛','Meat and seafood':'🐟','Bakery':'🍞','Frozen food':'🧊','Pantry':'🥫','Drinks':'🧃','Household':'🧼','Other':'🛒'};
const SUGGESTIONS=['Bananas','Tomatoes','Onion','Potatoes','Kumala','Cassava','Coconut milk','Rice','Eggs','Milk','Bread','Chicken','Fish','Tinned tuna','Cooking oil','Sugar','Tea','Water','Laundry powder','Soap'];
const KEY='fiji-grocery-v1';
const blank=()=>({items:[],usual:['Bananas','Milk','Bread','Eggs','Rice'],pantry:[],history:[],budget:0,household:'My household',lastList:[],updatedAt:Date.now()});
let pinBuffer='',pinUnlocked=false,passcodeEmail=localStorage.getItem('fiji-last-email')||'',pinBusy=false,pinWrongAttempts=0,pinBlockedUntil=0,sessionReady=false;
let data;try{data={...blank(),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{data=blank()}
let activeListId=null,syncReady=false,syncChannel=null,syncTimer=null,lastServerItems=new Map(),pendingChanges=new Map(),conflictDetected=false,memberNames=new Map(),stateChannel=null,stateTimer=null,stateReady=false,statePending=false;
const queueKey=houseId=>`fiji-sync-${signedInUser?.id||'guest'}-${houseId}`;
const persistQueue=()=>{if(activeHousehold&&signedInUser)localStorage.setItem(queueKey(activeHousehold.id),JSON.stringify([...pendingChanges]))};
const storageKey=()=>activeListId&&signedInUser&&activeHousehold?`${KEY}-${signedInUser.id}-${activeHousehold.id}`:KEY;
const save=()=>{data.updatedAt=Date.now();localStorage.setItem(storageKey(),JSON.stringify(data));document.querySelector('#sync-label').textContent=activeListId?'Saved on this device · waiting to sync':'Saved on this device';document.querySelector('#updated-note').textContent='Updated just now';renderAll();if(activeListId){collectLocalChanges();scheduleSync();queueHouseholdState()}};
function collectLocalChanges(){if(!syncReady||!activeListId)return;const current=new Map(data.items.map(i=>[i.id,i]));for(const [id,item]of current){const old=lastServerItems.get(id);if(!old||old.is_deleted||!sameItem(item,rowToItem(old)))pendingChanges.set(id,{item,deleted:false,updatedAt:Number(item.updatedAt)||Date.now()})}for(const [id,row]of lastServerItems){if(!row.is_deleted&&!current.has(id))pendingChanges.set(id,{item:null,deleted:true,updatedAt:Date.now()})}persistQueue()}
function scheduleSync(){clearTimeout(syncTimer);if(!navigator.onLine)return;syncTimer=setTimeout(syncPendingChanges,500)}
const money=n=>'FJD $'+(Number(n)||0).toFixed(2);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function categoryFor(name){const n=name.toLowerCase();const map={'Produce':['banana','tomato','onion','potato','kumala','cassava','taro','dalo','cabbage','lettuce','carrot','apple','orange','lemon','fruit','vegetable','spinach','beans','capsicum','ginger','garlic'],'Dairy':['milk','egg','cheese','butter','yoghurt','yogurt','cream'],'Meat and seafood':['chicken','beef','lamb','pork','fish','tuna','prawn','seafood','meat','sausage'],'Bakery':['bread','bun','cake','flour','roti','bakery'],'Frozen food':['frozen','ice cream'],'Drinks':['water','juice','drink','soda','tea','coffee','cola'],'Household':['soap','detergent','washing','laundry','cleaner','toilet','tissue','shampoo','dishwash'],'Pantry':['rice','sugar','salt','oil','coconut milk','can','tinned','pasta','noodle','flour','cereal','sauce','spice','beans','lentil']};for(const cat of CATEGORIES){if((map[cat]||[]).some(w=>n.includes(w)))return cat}return'Other'}
function finalPrice(item){const qty=Number(item.quantity)||1,p=Number(item.price)||0,d=Number(item.discountValue)||0;let unit=p;if(item.discountType==='percent')unit=Math.max(0,p*(1-d/100));if(item.discountType==='fixed')unit=Math.max(0,p-d);if(item.discountType==='special')unit=item.discountValue!==''&&item.discountValue!=null?d:p;return unit*qty}
function totals(){const items=data.items.filter(i=>!i.alreadyHave);const before=items.reduce((s,i)=>s+(Number(i.price)||0)*(Number(i.quantity)||1),0),after=items.reduce((s,i)=>s+finalPrice(i),0);return{before,after,saved:before-after}}
function renderHome(){const target=document.querySelector('#shopping-list');if(!data.items.length)target.innerHTML='<div class="empty-state">Your list is empty. Add your first item.</div>';else target.innerHTML=CATEGORIES.map(cat=>{const rows=data.items.filter(i=>i.category===cat);if(!rows.length)return'';return `<div class="aisle"><h3 class="aisle-title"><span>${EMOJI[cat]}</span>${cat}</h3>${rows.map(i=>{const price=finalPrice(i),old=(Number(i.price)||0)*(Number(i.quantity)||1),saving=old-price;return `<article class="grocery-item ${i.bought?'is-bought':''} ${i.alreadyHave?'is-already-have':''}"><input class="check-box" type="checkbox" data-toggle="${i.id}" ${i.bought?'checked':''} aria-label="Mark ${esc(i.name)} as bought"><div><div class="item-name">${esc(i.name)}</div><div class="item-details">${esc(i.quantity||1)} ${esc(i.unit||'pieces')}${i.notes?' · '+esc(i.notes):''}${i.alreadyHave?' · Already have at home':''}${i.addedBy?' · Added by '+esc(i.addedBy):''}</div></div><div class="item-price">${i.alreadyHave?'At home':i.price!==''&&i.price!=null?money(price):''}${saving>0&&!i.alreadyHave?`<span class="old-price">${money(old)}</span><span class="saving-label">Save ${money(saving)}</span>`:''}</div><div class="item-tools"><button class="mini-button" data-edit="${i.id}">Edit</button><button class="mini-button" data-price="${i.id}">${i.price!==''&&i.price!=null?'Edit price':'Add price'}</button><label class="move-label">Move<select class="mini-select" data-move="${i.id}" aria-label="Move ${esc(i.name)} to another aisle">${CATEGORIES.map(c=>`<option ${i.category===c?'selected':''}>${c}</option>`).join('')}</select></label><button class="mini-button" data-have="${i.id}">${i.alreadyHave?'Need to buy':'Already have'}</button><button class="mini-button delete-mini" data-delete="${i.id}">Delete</button></div></article>`}).join('')}</div>`}).join('');const t=totals();document.querySelector('#total-before').textContent=money(t.before);document.querySelector('#total-savings').textContent=money(t.saved);document.querySelector('#total-final').textContent=money(t.after);document.querySelector('#item-count').textContent=`${data.items.length} ${data.items.length===1?'item':'items'}`;document.querySelector('#budget-summary').textContent=data.budget?`${money(Math.max(0,data.budget-t.after))} left from your ${money(data.budget)} budget.`:'Set a budget to see what is left.';document.querySelector('#usual-items').innerHTML=data.usual.length?data.usual.map(x=>`<button class="usual-chip" data-usual="${esc(x)}"><span>+</span>${esc(x)}</button>`).join(''):'<span class="hint">Save items you buy often here.</span>'}
function expiryText(date){if(!date)return['No expiry date','good'];let diff=Math.ceil((new Date(date+'T23:59:59')-new Date())/86400000);if(diff<0)return['Expired','bad'];if(diff===0)return['Expires today','bad'];if(diff<=3)return['Use soon',''];return['Use by '+new Date(date+'T12:00:00').toLocaleDateString(),'good']}
function renderPantry(){const el=document.querySelector('#pantry-list');const pantry=data.pantry.filter(p=>!p.deleted);el.innerHTML=pantry.length?`<div class="panel"><h2>At home</h2>${pantry.map((p,i)=>{const [label,cls]=expiryText(p.expiry);return `<div class="row-card"><span><strong>${esc(p.name)}</strong><div class="row-sub">${esc(p.quantity||'Amount not set')}${p.notes?' · '+esc(p.notes):''}</div></span><span class="expiry ${cls}">${label}</span><button class="mini-button" data-pantry-add="${i}">Add to list</button><button class="mini-button" data-pantry-remove="${i}">×</button></div>`}).join('')}</div>`:'<div class="empty-state">No pantry items yet.</div>'}
function renderAll(){renderHome();renderPantry();document.querySelector('#history-list').innerHTML=data.history.length?data.history.map(h=>`<div class="row-card"><span>${new Date(h.date).toLocaleDateString()}<div class="row-sub">${h.count} items</div></span><strong>${money(h.spent)}</strong></div>`).join(''):'<p class="empty-inline">Your past trips will show here.</p>';document.querySelector('#budget-input').value=data.budget||'';document.querySelector('#household-name').value=data.household||'';document.querySelector('#category-guide').innerHTML=CATEGORIES.map(c=>`<div class="row-card"><span>${EMOJI[c]} &nbsp;${c}</span><span class="row-sub">${data.items.filter(i=>i.category===c).length} items</span></div>`).join('')}
function openItem(item,focus='name'){const form=document.querySelector('#item-form');form.reset();form.elements.id.value=item?.id||'';form.elements.name.value=item?.name||'';form.elements.quantity.value=item?.quantity||1;form.elements.unit.value=item?.unit||'pieces';form.elements.price.value=item?.price||'';form.elements.discountType.value=item?.discountType||'none';form.elements.discountValue.value=item?.discountValue||'';form.elements.category.value=item?.category||categoryFor(item?.name||'')||'Other';form.elements.notes.value=item?.notes||'';document.querySelector('#dialog-title').textContent=item?(focus==='price'?'Add or edit price':focus==='category'?'Move item':'Edit item'):'Add an item';document.querySelector('#delete-item').hidden=!item;document.querySelector('#item-dialog').showModal();requestAnimationFrame(()=>form.elements[focus]?.focus())}
function addItem(name,extra={}){const normalized=name.trim();if(!normalized)return;const exists=data.items.find(i=>i.name.toLowerCase()===normalized.toLowerCase()&&!i.bought);if(exists){exists.quantity=Number(exists.quantity||1)+Number(extra.quantity||1);exists.alreadyHave=false;exists.updatedAt=Date.now()}else data.items.push({id:crypto.randomUUID(),name:normalized,quantity:extra.quantity||1,unit:extra.unit||'pieces',category:extra.category||categoryFor(normalized),price:extra.price||'',discountType:'none',discountValue:'',notes:extra.notes||'',bought:false,alreadyHave:false,addedById:signedInUser?.id||null,addedBy:'You',updatedAt:Date.now()});if(!data.usual.includes(normalized))data.usual.unshift(normalized);data.usual=data.usual.slice(0,12);save()}
document.querySelector('#category-select').innerHTML=CATEGORIES.map(c=>`<option>${c}</option>`).join('');document.querySelector('#today-label').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}).toUpperCase();
