document.addEventListener('click',e=>{const t=e.target.closest('[data-pick],[data-usual],[data-edit],[data-price],[data-delete],[data-toggle],[data-have],[data-pantry-add],[data-pantry-remove]');if(!t)return;if(t.dataset.pick||t.dataset.usual){addItem(t.dataset.pick||t.dataset.usual);document.querySelector('#quick-name').value='';document.querySelector('#suggestions').hidden=true}if(t.dataset.edit)openItem(data.items.find(i=>i.id===t.dataset.edit));if(t.dataset.price)openItem(data.items.find(i=>i.id===t.dataset.price),'price');if(t.dataset.delete)deleteListItem(t.dataset.delete);if(t.dataset.have){const item=data.items.find(i=>i.id===t.dataset.have);if(item){item.alreadyHave=!item.alreadyHave;item.updatedAt=Date.now();save()}}if(t.dataset.toggle){const i=data.items.find(i=>i.id===t.dataset.toggle);if(i){i.bought=t.checked;i.updatedAt=Date.now();save()}}if(t.dataset.pantryAdd!==undefined){const p=data.pantry[Number(t.dataset.pantryAdd)];addItem(p.name,{quantity:1,notes:p.quantity?'At home: '+p.quantity:''})}if(t.dataset.pantryRemove!==undefined){data.pantry[Number(t.dataset.pantryRemove)].deleted=true;data.pantry[Number(t.dataset.pantryRemove)].updatedAt=Date.now();save()}});
document.querySelector('#item-form').onsubmit=e=>{e.preventDefault();const f=e.target,id=f.elements.id.value,obj={name:f.elements.name.value.trim(),quantity:f.elements.quantity.value||1,unit:f.elements.unit.value,price:f.elements.price.value,discountType:f.elements.discountType.value,discountValue:f.elements.discountValue.value,category:f.elements.category.value,notes:f.elements.notes.value};if(id)Object.assign(data.items.find(i=>i.id===id),obj,{updatedAt:Date.now()});else data.items.push({id:crypto.randomUUID(),...obj,bought:false,alreadyHave:false,addedById:signedInUser?.id||null,addedBy:'You',updatedAt:Date.now()});if(!data.usual.includes(obj.name))data.usual.unshift(obj.name);document.querySelector('#item-dialog').close();save()};
function deleteListItem(id){const item=data.items.find(i=>i.id===id);if(!item||!confirm('Delete this item from your list?'))return;data.items=data.items.filter(i=>i.id!==id);document.querySelector('#item-dialog').close();save()}document.querySelector('#delete-item').onclick=()=>deleteListItem(document.querySelector('#item-form').elements.id.value);
