document.querySelector('#budget-form').onsubmit=e=>{e.preventDefault();data.budget=Number(document.querySelector('#budget-input').value)||0;data.budgetUpdatedAt=Date.now();save()};document.querySelector('#spent-form').onsubmit=e=>{e.preventDefault();const spent=Number(document.querySelector('#spent-input').value);if(!spent)return;data.history.unshift({id:crypto.randomUUID(),date:new Date().toISOString(),spent,count:data.items.length});data.lastList=data.items.map(i=>({...i}));data.items=[];document.querySelector('#spent-input').value='';save()};
document.querySelector('#privacy-button').onclick=()=>document.querySelector('[data-goto="privacy"]').click();document.querySelector('#delete-data').onclick=async()=>{if(!confirm('Clear this app data from this browser? Your household list will stay online.'))return;if(signedInUser)localStorage.removeItem(`fiji-pin-${signedInUser.id}`);localStorage.removeItem(KEY);if(signedInUser&&activeHousehold){localStorage.removeItem(`${KEY}-${signedInUser.id}-${activeHousehold.id}`);localStorage.removeItem(`fiji-pin-${signedInUser.id}`);localStorage.removeItem(queueKey(activeHousehold.id));localStorage.removeItem(`fiji-state-${signedInUser.id}-${activeHousehold.id}`);pendingChanges.clear();lastServerItems.clear();data=blank();syncReady=false;statePending=false;await refreshSharedList(true);await loadHouseholdState(activeHousehold.id)}else{data=blank();save();showMessage('Data cleared','Your data on this device has been cleared.')}};
