function mergeHouseholdPayload(a={},b={}){
 const byId=new Map();for(const item of [...(a.pantry||[]),...(b.pantry||[])]){if(!item.id)continue;const old=byId.get(item.id);if(!old||Number(item.updatedAt||0)>=Number(old.updatedAt||0))byId.set(item.id,item)}
 const trips=new Map();for(const trip of [...(a.history||[]),...(b.history||[])]){if(!trip.id)continue;trips.set(trip.id,trip)}
 const bWins=Number(b.budgetUpdatedAt||0)>Number(a.budgetUpdatedAt||0);
 return{pantry:[...byId.values()],history:[...trips.values()].sort((x,y)=>String(y.date).localeCompare(String(x.date))),budget:bWins?Number(b.budget)||0:Number(a.budget)||0,budgetUpdatedAt:Math.max(Number(a.budgetUpdatedAt||0),Number(b.budgetUpdatedAt||0)),updatedAt:Math.max(Number(a.updatedAt||0),Number(b.updatedAt||0))}
}
function queueHouseholdState(){if(!activeHousehold||!signedInUser)return;data.pantry=data.pantry.map(p=>p.id?p:{...p,id:crypto.randomUUID(),updatedAt:Date.now()});data.history=data.history.map(h=>h.id?h:{...h,id:crypto.randomUUID()});const key=`fiji-state-${signedInUser.id}-${activeHousehold.id}`;const next={pantry:data.pantry,history:data.history,budget:Number(data.budget)||0,budgetUpdatedAt:Number(data.budgetUpdatedAt)||0,updatedAt:Date.now()};try{const old=JSON.parse(localStorage.getItem(key)||'{}');localStorage.setItem(key,JSON.stringify(mergeHouseholdPayload(old,next)))}catch{localStorage.setItem(key,JSON.stringify(next))}statePending=true;clearTimeout(stateTimer);if(navigator.onLine&&stateReady)stateTimer=setTimeout(syncHouseholdState,600)}
async function loadHouseholdState(houseId){if(!authClient||!signedInUser||!houseId)return;if(stateChannel){await authClient.removeChannel(stateChannel);stateChannel=null}const key=`fiji-state-${signedInUser.id}-${houseId}`;let local={};try{local=JSON.parse(localStorage.getItem(key)||'{}')}catch{}if(!local.updatedAt){data.pantry=data.pantry.map(p=>p.id?p:{...p,id:crypto.randomUUID(),updatedAt:Date.now()});data.history=data.history.map(h=>h.id?h:{...h,id:crypto.randomUUID()});local={pantry:data.pantry,history:data.history,budget:Number(data.budget)||0,budgetUpdatedAt:Number(data.budgetUpdatedAt)||0,updatedAt:Number(data.updatedAt)||Date.now()}}const {data:row,error}=await authClient.from('household_app_state').select('payload').eq('household_id',houseId).maybeSingle();if(error){stateReady=true;statePending=!!local.updatedAt;document.querySelector('#sync-label').textContent='Offline ? changes saved here';return}const merged=mergeHouseholdPayload(row?.payload||{},local);data.pantry=merged.pantry;data.history=merged.history;data.budget=merged.budget;data.budgetUpdatedAt=merged.budgetUpdatedAt;localStorage.setItem(key,JSON.stringify(merged));localStorage.setItem(storageKey(),JSON.stringify(data));stateReady=true;statePending=Number(merged.updatedAt||0)>Number(row?.payload?.updatedAt||0);renderAll();if(statePending)syncHouseholdState();stateChannel=authClient.channel(`household-state-${houseId}`).on('postgres_changes',{event:'*',schema:'public',table:'household_app_state',filter:`household_id=eq.${houseId}`},async()=>{if(statePending)return;const {data:updated}=await authClient.from('household_app_state').select('payload').eq('household_id',houseId).maybeSingle();if(updated?.payload){const result=mergeHouseholdPayload(updated.payload,{pantry:data.pantry,history:data.history,budget:data.budget,budgetUpdatedAt:data.budgetUpdatedAt,updatedAt:data.updatedAt});data.pantry=result.pantry;data.history=result.history;data.budget=result.budget;data.budgetUpdatedAt=result.budgetUpdatedAt;localStorage.setItem(key,JSON.stringify(result));localStorage.setItem(storageKey(),JSON.stringify(data));renderAll();document.querySelector('#updated-note').textContent='Household shopping data updated'}}).subscribe()}
async function syncHouseholdState(){if(!stateReady||!statePending||!navigator.onLine||!activeHousehold||!signedInUser)return;const key=`fiji-state-${signedInUser.id}-${activeHousehold.id}`;let local={};try{local=JSON.parse(localStorage.getItem(key)||'{}')}catch{}const {data:row,error:readError}=await authClient.from('household_app_state').select('payload').eq('household_id',activeHousehold.id).maybeSingle();if(readError)return;const payload=mergeHouseholdPayload(row?.payload||{},local);const {error}=await authClient.from('household_app_state').upsert({household_id:activeHousehold.id,payload,updated_at:new Date().toISOString()},{onConflict:'household_id'});if(error){document.querySelector('#sync-label').textContent='Offline ? changes saved here';return}localStorage.setItem(key,JSON.stringify(payload));statePending=false;document.querySelector('#sync-label').textContent='Synced with household'}
