document.querySelector('#save-household').onclick=async()=>{if(!signedInUser){openAuth('login');return}const name=document.querySelector('#household-name').value.trim();if(!name){showMessage('Add a group name','Type a name for your household first.');return}const {data:house,error}=await authClient.from('households').insert({name,owner_id:signedInUser.id}).select('id,name,invite_code').single();if(error){showMessage('Could not create group',authErrorText(error));return}await authClient.from('shopping_lists').insert({household_id:house.id,name:'Shopping list'});document.querySelector('#household-name').value='';await loadHouseholds();showMessage('Group created',`Share invite code ${house.invite_code} with your household.`)};
document.querySelector('#join-household').onclick=async()=>{if(!signedInUser){openAuth('login');return}const code=document.querySelector('#join-code').value.trim();if(!code){showMessage('Enter an invite code','Ask a household member for their invite code.');return}const {error}=await authClient.rpc('join_household',{p_invite_code:code});if(error){showMessage('Could not join group',authErrorText(error));return}document.querySelector('#join-code').value='';await loadHouseholds();showMessage('You joined the group','You are now a member of this household.')};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-copy-invite]');if(!b)return;try{await navigator.clipboard.writeText(b.dataset.copyInvite);showMessage('Code copied','Share this invite code with someone you trust.')}catch{showMessage('Invite code',b.dataset.copyInvite)}});
document.querySelector('#join-code').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();document.querySelector('#join-household').click()}});window.addEventListener('online',()=>{if(pendingChanges.size)scheduleSync();else if(activeListId)refreshSharedList(false);if(statePending)syncHouseholdState()});
if('serviceWorker'in navigator&&location.protocol!=='file:')window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(()=>{}));renderAll();

document.querySelector('#open-add-item').onclick=()=>openItem(null);document.addEventListener('change',e=>{const select=e.target.closest('[data-move]');if(!select)return;const item=data.items.find(i=>i.id===select.dataset.move);if(item&&item.category!==select.value){item.category=select.value;item.updatedAt=Date.now();save()}});
